/* A PROP'S COLLISION IS ITS DRAWN MESH: each mesh `prop_<kind>` of a park's props GLB written out as plain data the sim reads (positions as
 * the GLB's own float32 values, exactly; its triangles' indices), with its size. One source: the GLB; this file is generated, never edited.
 *   node tools/props_col.mjs <props.glb> <out.js> */
import fs from 'node:fs';
import path from 'node:path';
const [glb, out] = process.argv.slice(2);
const buf = fs.readFileSync(glb), jl = buf.readUInt32LE(12), J = JSON.parse(buf.slice(20, 20 + jl).toString('utf8')), bin = buf.slice(20 + jl + 8);
const acc = (i) => { const a = J.accessors[i], v = J.bufferViews[a.bufferView], n = { SCALAR: 1, VEC2: 2, VEC3: 3 }[a.type], C = { 5126: Float32Array, 5125: Uint32Array, 5123: Uint16Array, 5121: Uint8Array }[a.componentType];
  return new C(bin.buffer, bin.byteOffset + (v.byteOffset || 0) + (a.byteOffset || 0), a.count * n); };
const meshes = {};
for (const nd of J.nodes) {
  if (nd.mesh == null) continue; const me = J.meshes[nd.mesh], kind = (nd.name || me.name).replace(/^prop_/, '').replace(/\.\d+$/, '');
  if (nd.rotation || nd.scale || (nd.translation && nd.translation.some((v) => Math.abs(v) > 1e-9))) throw new Error(kind + ': a prop\'s node must stand at the origin, unturned');
  const pos = [], idx = [];
  for (const pr of me.primitives) { const P = acc(pr.attributes.POSITION), I = pr.indices != null ? acc(pr.indices) : P.map((_, k) => k).filter((k) => k % 3 === 0); const base = pos.length / 3; for (const v of P) pos.push(v); for (const k of I) idx.push(base + k); }
  const xs = [], ys = [], zs = []; for (let k = 0; k < pos.length; k += 3) { xs.push(pos[k]); ys.push(pos[k + 1]); zs.push(pos[k + 2]); }
  meshes[kind] = { size: [Math.max(...xs) - Math.min(...xs), Math.max(...ys) - Math.min(...ys), Math.max(...zs) - Math.min(...zs)], box: [Math.min(...xs), Math.min(...zs), Math.max(...xs), Math.max(...zs)], pos, idx };
}
/* the positions as the GLB's own float32 bytes (little-endian, base64), the indices as 16-bit: exact, and a sixth of the decimals' size */
const b64 = (T) => Buffer.from(T.buffer, T.byteOffset, T.byteLength).toString('base64');
const body = Object.entries(meshes).map(([k, m]) => `  ${k}: { size: ${JSON.stringify(m.size.map((v) => +v.toFixed(4)))}, box: ${JSON.stringify(m.box)}, pos: f32('${b64(Float32Array.from(m.pos))}'), idx: u16('${b64(Uint16Array.from(m.idx))}') },`).join('\n');
fs.writeFileSync(out, `/* GENERATED by tools/props_col.mjs from ${path.basename(glb)} — never edited by hand: each prop's collision is its drawn mesh's own
 * triangles (positions the GLB's float32 values exactly). box: its footprint on the ground [x0, z0, x1, z1] about its foot. */
const bytes = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
const f32 = (s) => { const b = bytes(s); return new Float32Array(b.buffer, b.byteOffset, b.byteLength / 4); };
const u16 = (s) => { const b = bytes(s); return new Uint16Array(b.buffer, b.byteOffset, b.byteLength / 2); };
export const PROP_MESHES = {
${body}
};
`);
console.log('wrote', out, Object.entries(meshes).map(([k, m]) => `${k} ${m.idx.length / 3} tris ${m.size.map((v) => v.toFixed(2)).join('×')}`).join(' · '));
